<template><div class="option-page"><el-form inline><el-form-item label="合约"><el-input v-model="thscode" style="width:280px" /></el-form-item><el-button type="primary" @click="load">查询时间轴</el-button></el-form><el-descriptions v-if="data" :column="3" border><el-descriptions-item label="交易日">{{ data.trade_date }}</el-descriptions-item><el-descriptions-item label="时区">{{ data.timezone }}</el-descriptions-item><el-descriptions-item label="合约">{{ data.thscode }}</el-descriptions-item></el-descriptions><el-table v-if="data" :data="stages" class="table"><el-table-column prop="stage" label="阶段" /><el-table-column prop="ranges" label="交易时段" /></el-table></div></template>
<script setup name="OptionTimeline">
import { computed, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { getMarketOptionTimeline } from '@/api/future/option'
const thscode=ref('IO2610-C-4000.CFE'); const data=ref(null); const format=value=>new Date(value).toLocaleString('zh-CN',{hour12:false}); const stages=computed(()=>[...(data.value?.trade_stages||[]).map(item=>({stage:item.trade_period,ranges:(item.trade_ranges||[]).map(range=>`${format(range.begin_time)} ~ ${format(range.end_time)}`).join('\n')})),...(data.value?.exchange_sessions||[]).map(item=>({stage:item.trade_phase,ranges:(item.phase_range||[]).map(range=>`${format(range.begin_time)} ~ ${format(range.end_time)}`).join('\n')}))]); function load(){getMarketOptionTimeline(thscode.value).then(response=>{data.value=response.data}).catch(()=>ElMessage.error('交易时间轴查询失败'))}
</script><style scoped>.option-page{padding:20px}.table{margin-top:16px}.table :deep(.cell){white-space:pre-line}</style>
